import{At as e,Pt as t,Ut as n,gt as r,ht as i,mt as a,n as o,pt as s,ut as c}from"./chunks/framework.BrKcMR_c.js";var l=JSON.parse(`{"title":"ADR-0079: Shared Aurora rendering worker","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/0079-shared-aurora-worker.md","filePath":"adrs/0079-shared-aurora-worker.md","lastUpdated":1789092097000}`),u={name:`adrs/0079-shared-aurora-worker.md`};function d(o,l,u,d,f,p){let m=t(`Term`);return e(),s(`div`,null,[l[3]||=a(`<h1 id="adr-0079-shared-aurora-rendering-worker" tabindex="-1">ADR-0079: Shared Aurora rendering worker <a class="header-anchor" href="#adr-0079-shared-aurora-rendering-worker" aria-label="Permalink to “ADR-0079: Shared Aurora rendering worker”">​</a></h1><p>Status: Accepted · Refines <a href="/adrs/0041-website-as-vite-vue-spa">ADR-0041</a> and <a href="/adrs/0077-host-coordination-and-resource-lifetimes">ADR-0077</a></p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2>`,3),c(`p`,null,[l[1]||=i(`The website and documentation reuse Aurora backgrounds across page, panel and tile surfaces. Each canvas previously acquired its own graphics device and ran its drawing loop on the main thread. Mobile navigation must remain responsive while decorative rendering runs. Local network HTTP previews cannot exercise browser capabilities that require a secure `,-1),r(m,{term:`context-window`},{default:n(()=>[...l[0]||=[i(`context`,-1)]]),_:1}),l[2]||=i(`.`,-1)]),l[4]||=a(`<h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Use one dedicated module worker per page with one WebGPU device and pipeline. Each mounted decoration owns a lease and transfers its canvas only after the worker confirms that it can create a pipeline. The Vue component owns its intersection observer; the browser adapter owns resize, scroll and document visibility listeners. The worker owns graphics resources and scheduling.</p><p>The worker submits one batch for visible surfaces, at up to 30 frames per second, and waits for completion before scheduling another. Canvas dimensions are capped at 1280 pixels per axis while preserving aspect ratio. Reduced motion renders once per input change. Uniforms, messages and rendering code have no Vue dependency.</p><p>Unsupported desktop browsers retain main-thread WebGPU, WebGL2 and CSS fallback paths. Unsupported touch browsers use CSS. Failure after canvas transfer restores CSS; it does not attempt to reuse a transferred canvas on the main thread. Device loss, setup failure and worker errors release resources. The final lease release terminates the worker, including pending initialization.</p><p>Provide an explicit HTTPS development command. Website and docs share one secure public origin, while the proxied docs backend stays on loopback. Certificate paths are supplied by the developer and private keys stay outside the repository. Existing servers are never stopped to claim a port.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><p>Drawing orchestration no longer competes with input handling on browsers with worker WebGPU. GPU work and browser compositing still share device resources, so a worker does not fix expensive CSS effects. The mobile filter fixes remain in place, and physical-device acceptance remains necessary.</p><p>No runtime dependency or external request is added. Tests cover shared ownership, pending setup disposal, transfer failure, device loss, bounded submissions, visibility suspension and reduced motion. Website and docs builds verify both consumers.</p><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to “Alternatives considered”">​</a></h2><p>One worker per canvas would keep duplicated devices and scheduling overhead. Keeping all drawing on the main thread would preserve contention as more surfaces are added. Disabling animation on every touch device would discard capable hardware; capability checks with a static fallback retain the effect where supported.</p>`,10)])}var f=o(u,[[`render`,d]]);export{l as __pageData,f as default};